mapper.update:
UPDATE t_i18n_namespace
SET namespace_name = #{next.namespaceName}, description = #{next.description},
    sort_order = #{next.sortOrder}, version = version + 1, updated_by = #{next.updatedBy},
    update_time = #{next.updateTime}
WHERE namespace_id = #{row.namespaceId} AND version = #{row.version}
